import type { BreadcrumbsContextType } from "../breadcrumbs.types";

import { createContext, useContext } from "react";

export const BreadcrumbsContext = createContext<BreadcrumbsContextType | undefined>(undefined);

export const useBreadcrumbs = () => {
  const context = useContext(BreadcrumbsContext);
  if (!context) {
    throw new Error("useBreadcrumbs must be used within a <Breadcrumbs> component");
  }
  return context;
};
